{"cards": [{"node_code": "N_4061e948e6e699c1", "definition": "研究为整车制造提供配套零部件的专门工厂，涵盖其生产布局、工艺装备配置、质量控制体系及与总装厂的协同管理。", "boundary": "本节点聚焦于“零部件”生产工厂的组织与工程。边界在于区分“零部件厂”与“整车制造厂”（后者侧重总装与整车性能）、“零部件厂”与“零部件设计”（设计侧重结构原理，归汽车结构部件）。若内容涉及具体零件的加工工艺参数，归汽车制造工艺；若涉及零部件厂的车间布局、设备选型及生产组织，归本节点。", "includes": ["发动机、底盘、车身等零部件专用工厂的规划与设计", "零部件生产线的设备配置、工装夹具及生产流程管理", "零部件厂的质量保证体系及与整车厂的供应链协同"], "excludes": ["零部件的结构设计理论与材料选择", "整车总装线的布局与管理"], "sibling_distinctions": [{"other_code": "N_7815962533e28508", "rule": "工厂设计通常指整车制造厂的总体设计；汽车零部件厂特指配套件生产工厂的专项设计与管理。"}, {"other_code": "N_0802d8516fe7809c", "rule": "工厂设备及安装侧重通用或整厂设备；汽车零部件厂侧重特定零部件生产所需的专用工艺装备与产线。"}], "cross_boundary_rule": "若内容涉及“零部件加工的具体工艺方法”，主挂载汽车制造工艺；若涉及“零部件工厂的整体布局与生产组织”，主挂载汽车零部件厂。"}, {"node_code": "N_b04d3cd09f23c68f", "definition": "研究汽车制造厂内部用于停放、周转或临时存储车辆及大型部件的专用设施，包括其结构设计、功能分区及与生产物流的衔接。", "boundary": "本节点聚焦于工厂内部的“车库”设施。边界在于区分“工厂车库”与“社会公共停车场”（后者归城市交通或建筑类）、“工厂车库”与“仓库”（仓库侧重静态存储，车库侧重车辆停放与移动）。若内容涉及车库的建筑结构、通风照明及内部交通流线设计，归本节点；若涉及车辆长期仓储管理，归贮藏运输。", "includes": ["制造厂内新车停放区、试验车库及大型部件暂存库的设计", "车库的建筑结构、环境控制（通风、照明）及安全防护设施", "车库与生产线、物流通道的衔接布局及车辆周转效率优化"], "excludes": ["城市公共停车场的规划与管理", "车辆长期静态仓储的库存管理策略"], "sibling_distinctions": [{"other_code": "N_46379888d3aa778e", "rule": "贮藏运输侧重物资的存储管理与厂内物流调度；车库侧重车辆及大型部件的物理停放设施与空间设计。"}, {"other_code": "N_7815962533e28508", "rule": "工厂设计涵盖全厂总体布局；车库是工厂设计中特定的功能分区设施，本节点深入其专项设计细节。"}], "cross_boundary_rule": "若内容涉及“车库内的车辆调度算法”，主挂载贮藏运输；若涉及“车库建筑结构及空间布局”，主挂载车库。"}, {"node_code": "N_216690fe22c3a0e8", "definition": "研究汽车制造生产过程中保障人员安全、预防职业危害及改善作业环境的工程技术与管理措施，涵盖安全规程、防护设备及卫生标准。", "boundary": "本节点聚焦于生产过程中的“安全”与“卫生”。边界在于区分“生产技术安全”与“产品安全”（产品安全归汽车工程或质量节点）、“生产技术安全”与“工厂设施安全”（如建筑结构安全，归工厂设计）。若内容涉及焊接烟尘治理、噪声控制、机械防护及安全生产管理体系，归本节点。", "includes": ["汽车制造车间的机械安全防护、电气安全及消防安全技术", "职业卫生措施，如粉尘、噪声、有毒有害气体的治理与监测", "安全生产管理制度、操作规程及事故预防与应急处理"], "excludes": ["汽车整车的安全性能设计（如碰撞安全）", "工厂建筑结构本身的抗震或防火设计"], "sibling_distinctions": [{"other_code": "N_2a353dd9262c8378", "rule": "动力能源供应侧重能源的生产与分配；生产技术安全侧重能源使用过程中的安全防护与事故预防。"}, {"other_code": "N_0802d8516fe7809c", "rule": "工厂设备及安装侧重设备的选型与安装技术；生产技术安全侧重设备运行过程中的安全防护装置与操作规范。"}], "cross_boundary_rule": "若内容涉及“安全设备的选型与安装”，主挂载工厂设备及安装；若涉及“安全操作规程与职业健康标准”，主挂载生产技术安全和卫生。"}]}
